describe('Debounced Search Functionality', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should trigger search only after 300ms pause in typing', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Type in the search input field
    cy.get('[data-testid="search-input"]').type('cypress automation');

    // Wait for the debounce delay (300ms)
    cy.wait(350);

    // Verify the search API was called
    cy.wait('@searchRequest');

    // Verify the search results are displayed
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('contain', 'cypress automation');
  });

  it('should not trigger search during rapid typing', () => {
    // Intercept the search API call
    cy.intercept('GET', '/api/search*').as('searchRequest');

    // Type rapidly in the search input field
    cy.get('[data-testid="search-input"]').type('abc123def4');

    // Wait for a short period (less than debounce time)
    cy.wait(100);

    // Type more characters
    cy.get('[data-testid="search-input"]').type('ghi');

    // Wait for another short period
    cy.wait(150);

    // Verify the search API was NOT called
    cy.get('@searchRequest').should('not.exist');

    // Verify search results are not displayed
    cy.get('[data-testid="search-results"]').should('not.exist');

    // Verify the input field still contains the full text
    cy.get('[data-testid="search-input"]').should('have.value', 'abc123defghi');
  });
});
